"use client";

import { Icon as IconifyIcon, addCollection } from "@iconify/react";
import bundles from "@/lib/icon-bundles.json";

// Register every icon the app uses from the local bundle (58KB, generated by
// scripts/build-icons.mts) so nothing is fetched from api.iconify.design at
// runtime. Unknown icons still fall back to the API — re-run the script when
// you add new ones.
for (const bundle of bundles) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  addCollection(bundle as any);
}

export function Icon({
  icon,
  className,
  width = 20,
  style,
}: {
  icon: string;
  className?: string;
  width?: number;
  style?: React.CSSProperties;
}) {
  return (
    <IconifyIcon
      icon={icon}
      className={className}
      width={width}
      height={width}
      style={style}
      aria-hidden="true"
    />
  );
}
